// Logo oficial da JMT (Jobson de Moraes Transportes) — fornecida pela empresa (arquivo
// original em alta resolução), usada nos documentos gerados (planilhas de fatura via
// ExcelJS e no componente JmtLogo, variantes "full"/"compact" em tema claro) pra sempre
// bater com a marca real, em vez de uma recriação aproximada.
export const JMT_LOGO_BASE64 = "data:image/png;base64,";


// Recorte apenas do glifo/símbolo (sem o texto "JOBSON DE MORAES / TRANSPORTES") do mesmo
// arquivo oficial acima — usado no variant="icon" do JmtLogo (favicon, login, sidebar recolhida)
// pra bater exatamente com a marca real, em vez do símbolo recriado à mão em SVG.
export const JMT_ICON_BASE64 = "data:image/png;base64,";


// Mesmo recorte do símbolo acima, com o traço preto invertido para branco — usado quando
// theme="dark" (fundo escuro: cabeçalhos institucionais, portais públicos, sidebar expandida
// em tema escuro). O traço bronze permanece igual (já visível em fundo escuro).
export const JMT_ICON_DARK_BASE64 = "data:image/png;base64,";
